contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint256 d, uint256 w) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (d)); require(d <= 1000000000000000000000000000000);
        require(d > 0 && d <= address(this).balance);

        c.deposit{value: d}(); if (__ESBMC_reverted()) return;
        uint256 postDeposit = address(c).balance;
        uint256 thisBefore = address(this).balance;

        bool reverted;
        c.withdraw(w); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(reverted == (w > d) && (reverted ? address(c).balance == postDeposit : address(c).balance == postDeposit - w) && (reverted ? address(this).balance == thisBefore : address(this).balance == thisBefore + w));
    }
}

